#!/usr/bin/env python3
from __future__ import annotations

REQUIRED_BACKUP_TARGETS = (
    "vector_collections",
    "source_documents",
    "parser_config",
    "embedding_model_metadata",
    "collection_schema",
    "index_settings",
)


def missing_backup_targets(selected: list[str] | tuple[str, ...] | set[str]) -> tuple[str, ...]:
    selected_targets = set(selected)
    return tuple(target for target in REQUIRED_BACKUP_TARGETS if target not in selected_targets)


def backup_plan_is_complete(selected: list[str] | tuple[str, ...] | set[str]) -> bool:
    return not missing_backup_targets(selected)

from __future__ import annotations

REQUIRED_RAG_SIGNALS = (
    "retrieval_latency_seconds",
    "vector_db_query_latency_seconds",
    "retrieved_document_count",
    "empty_retrieval_total",
    "model_latency_seconds",
    "model_token_throughput",
    "request_errors_total",
    "gpu_memory_utilization",
)


def missing_rag_signals(enabled_signals: list[str] | tuple[str, ...] | set[str]) -> tuple[str, ...]:
    enabled = set(enabled_signals)
    return tuple(signal for signal in REQUIRED_RAG_SIGNALS if signal not in enabled)


def rag_observability_is_complete(enabled_signals: list[str] | tuple[str, ...] | set[str]) -> bool:
    return not missing_rag_signals(enabled_signals)

import importlib.util
import unittest
from pathlib import Path


SCRIPT_PATH = Path(__file__).resolve().parents[1] / "scripts/rag_observability_signals.py"
SPEC = importlib.util.spec_from_file_location("rag_observability_signals", SCRIPT_PATH)
rag_observability_signals = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(rag_observability_signals)


class RagObservabilitySignalsTests(unittest.TestCase):
    def test_complete_signal_set_passes(self):
        self.assertTrue(
            rag_observability_signals.rag_observability_is_complete(
                rag_observability_signals.REQUIRED_RAG_SIGNALS
            )
        )

    def test_missing_signals_are_reported(self):
        missing = rag_observability_signals.missing_rag_signals({"retrieval_latency_seconds"})

        self.assertIn("empty_retrieval_total", missing)
        self.assertIn("gpu_memory_utilization", missing)


if __name__ == "__main__":
    unittest.main()

from __future__ import annotations

REQUIRED_RETENTION_FIELDS = (
    "user_history_days",
    "operational_log_days",
    "anonymization_required",
    "backup_retention_days",
    "support_access_scope",
)


def missing_retention_fields(policy: dict[str, object]) -> tuple[str, ...]:
    return tuple(field for field in REQUIRED_RETENTION_FIELDS if field not in policy)


def retention_policy_is_reviewable(policy: dict[str, object]) -> bool:
    return not missing_retention_fields(policy)

from __future__ import annotations

REQUIRED_GPU_RUNBOOK_SECTIONS = (
    "driver_prerequisites",
    "container_runtime",
    "model_cache",
    "health_checks",
    "gpu_metrics",
    "rollback_path",
)


def missing_gpu_runbook_sections(sections: list[str] | tuple[str, ...] | set[str]) -> tuple[str, ...]:
    present = set(sections)
    return tuple(section for section in REQUIRED_GPU_RUNBOOK_SECTIONS if section not in present)


def gpu_runbook_is_complete(sections: list[str] | tuple[str, ...] | set[str]) -> bool:
    return not missing_gpu_runbook_sections(sections)
